const translations={en:{title:"Timeless Stories<br><small>Official Book Hub</small>",subtitle:"Quick access to all volumes and languages",select:"Select volume",qr:"Show QR Code",qrTitle:"Scan to open this page",close:"Close",followMe:"Follow me",volumes:{v1:"Volume 1",v2:"Volume 2",mirrors:"Spanish Mirrors (Upcoming)"}},es:{title:"Historias Eternas<br><small>Centro oficial de libros</small>",subtitle:"Acceso rápido a todos los volúmenes e idiomas",select:"Seleccionar volumen",qr:"Mostrar código QR",qrTitle:"Escanea para abrir esta página",close:"Cerrar",followMe:"Sígueme",volumes:{v1:"Volumen 1",v2:"Volumen 2",mirrors:"Espejos Españoles (Próximamente)"}},fr:{title:"Légendes Éternelles<br><small>Plateforme officielle des livres</small>",subtitle:"Accès rapide à tous les volumes et langues",select:"Sélectionner le volume",qr:"Afficher le code QR",qrTitle:"Scannez pour ouvrir cette page",close:"Fermer",followMe:"Suivez-moi",volumes:{v1:"Volume 1",v2:"Volume 2",mirrors:"Miroirs Espagnols (À venir)"}}};function detectLang(){const e=(navigator.language||"en").slice(0,2);return translations[e]?e:"en"}function applyTranslations(){const e=detectLang(),t=translations[e];document.getElementById("title").innerHTML=t.title,document.getElementById("subtitle").innerHTML=t.subtitle,document.getElementById("selectLabel").textContent=t.select,document.getElementById("qrButton").textContent=t.qr,document.getElementById("qrTitle").textContent=t.qrTitle,document.getElementById("closeModal").textContent=t.close,document.getElementById("followMe").textContent=t.followMe}applyTranslations();const data={v1:{preview:"img/volume1.png",links:{English:"https://a.co/d/1HQh5JM","Español":"https://a.co/d/5RiXGEZ","Français":"https://a.co/d/7EyHZZm"}},v2:{preview:"img/volume2.png",links:{English:"https://a.co/d/0HYJyAp","Español":"https://a.co/d/9GF2Ug3"}},mirrors:{preview:"img/mirrors.png",links:{"Notify me":"https://amzn.to/3YXGR5W"}}},select=document.getElementById("volumeSelect"),linksContainer=document.getElementById("linksContainer"),previewImage=document.getElementById("previewImage");function renderVolume(e){const t=data[e];linksContainer.innerHTML="",Object.entries(t.links).forEach((([e,t])=>{const l=document.createElement("a");l.className="link-btn",l.href=t,l.target="_blank",l.textContent=e,linksContainer.appendChild(l)})),previewImage.src=t.preview}function loadVolumes(){const e=detectLang(),t=(translations[e]||translations.en).volumes||translations.en.volumes,l=select.value;select.innerHTML="",Object.keys(data).forEach((e=>{const l=document.createElement("option");l.value=e,l.textContent=t[e]||translations.en.volumes[e]||e,select.appendChild(l)})),select.value=data[l]?l:Object.keys(data)[0]}select.addEventListener("change",(e=>{renderVolume(e.target.value)}));const qrButton=document.getElementById("qrButton"),qrModal=document.getElementById("qrModal"),closeModal=document.getElementById("closeModal"),qrImage=document.getElementById("qrImage");function generateQR(){const e=window.location.href;qrImage.src=`https://api.qrserver.com/v1/create-qr-code/?size=300x300&data=${encodeURIComponent(e)}`}qrButton.addEventListener("click",(e=>{e.preventDefault(),generateQR(),qrModal.style.display="flex"})),closeModal.addEventListener("click",(e=>{e.preventDefault(),qrModal.style.display="none"})),qrModal.addEventListener("click",(e=>{e.target===qrModal&&(qrModal.style.display="none")})),loadVolumes(),renderVolume(select.value);